    <div style={{ display: 'grid', gap: 16, maxWidth: 420 }}>
      {invitedEmail !== null && (
        <div role="status" aria-live="polite">
          <JxToast
            variant="success"
            title="Приглашение отправлено"
            message={`${invitedEmail} получил${notify ? ' письмо и' : ''} доступ с ролью «${roleLabel}».`}
            onClose={dismiss}
          />
        </div>
      )}

      <form onSubmit={submit} noValidate style={{ display: 'grid', gap: 16 }}>
        <JxInputField
          ref={emailRef}
          label="Электронная почта"
          type="email"
          name="email"
          required
          placeholder="teammate@company.com"
          autoComplete="email"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          onBlur={() => setTouched(true)}
          errorText={errorText}
          helperText="Приглашение действует 7 дней. Один адрес за раз."
        />

        <JxSelect
          label="Роль в команде"
          options={ROLES}
          value={role}
          onValueChange={setRole}
          placeholder="Выберите роль"
        />

        <JxSwitch
          label="Отправить уведомление на почту"
          name="notify"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <div style={{ display: 'flex', gap: 8 }}>
          <JxButton type="submit" variant="primary" disabled={!isValid}>
            Отправить приглашение
          </JxButton>
        </div>
      </form>
    </div>
  );
}

